import { defineConfig, loadEnv } from 'vite'
import react from '@vitejs/plugin-react'

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
  // Load env file based on `mode` in the current working directory.
  // Set the third parameter to '' to load all env regardless of the `VITE_` prefix.
  // We use (process as any).cwd() to satisfy TS constraints in some environments.
  const env = loadEnv(mode, (process as any).cwd(), '');

  // For Netlify/Vercel, process.env.API_KEY is often available directly in the build environment.
  // We prioritize the `env` object loaded by Vite (which includes .env files), 
  // then fall back to process.env (system environment variables).
  const apiKey = env.API_KEY || process.env.API_KEY;

  return {
    plugins: [react()],
    build: {
      outDir: 'build',
    },
    define: {
      // Replaces process.env.API_KEY in the client code with the string value of the key.
      'process.env.API_KEY': JSON.stringify(apiKey),
    },
  }
})

// Production-grade IndexedDB wrapper
import { UserProfile, AnalysisResult } from '../services/geminiService';
import type { HistoryItem, Mode } from '../App';

const DB_NAME = 'ChicSyncDB';
const DB_VERSION = 1;

export interface User {
  id?: number;
  email: string;
  name: string;
  passwordHash: string;
  salt: string;
  createdAt: number;
}

export interface StoredHistoryItem {
  id?: number;
  userId: number;
  timestamp: number;
  result: AnalysisResult;
  generatedImage: string | null;
  mode: Mode;
}

export interface StoredUserProfile {
  userId: number;
  profile: UserProfile;
}

class Database {
  private db: IDBDatabase | null = null;

  async connect(): Promise<IDBDatabase> {
    if (this.db) return this.db;

    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onerror = (event) => reject('Database error: ' + (event.target as any).error);

      request.onsuccess = (event) => {
        this.db = (event.target as IDBOpenDBRequest).result;
        resolve(this.db);
      };

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;

        // Users Store
        if (!db.objectStoreNames.contains('users')) {
          const userStore = db.createObjectStore('users', { keyPath: 'id', autoIncrement: true });
          userStore.createIndex('email', 'email', { unique: true });
        }

        // Profiles Store
        if (!db.objectStoreNames.contains('profiles')) {
          db.createObjectStore('profiles', { keyPath: 'userId' });
        }

        // History Store
        if (!db.objectStoreNames.contains('history')) {
          const historyStore = db.createObjectStore('history', { keyPath: 'id', autoIncrement: true });
          historyStore.createIndex('userId', 'userId', { unique: false });
          historyStore.createIndex('timestamp', 'timestamp', { unique: false });
        }
      };
    });
  }

  // Generic transaction helper
  private async transaction<T>(
    storeName: string,
    mode: IDBTransactionMode,
    operation: (store: IDBObjectStore) => IDBRequest<T> | void
  ): Promise<T> {
    const db = await this.connect();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, mode);
      const store = tx.objectStore(storeName);

      let request: IDBRequest<T> | void;
      try {
        request = operation(store);
      } catch (err) {
        reject(err);
        return;
      }

      tx.oncomplete = () => {
        if (request) resolve(request.result);
        else resolve(undefined as unknown as T);
      };

      tx.onerror = () => reject(tx.error);
    });
  }

  // --- User Operations ---

  async createUser(user: Omit<User, 'id'>): Promise<number> {
    return this.transaction<number>('users', 'readwrite', (store) => store.add(user));
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const db = await this.connect();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('users', 'readonly');
      const store = tx.objectStore('users');
      const index = store.index('email');
      const request = index.get(email);

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  // --- Profile Operations ---

  async getUserProfile(userId: number): Promise<UserProfile | null> {
    const result = await this.transaction<StoredUserProfile>('profiles', 'readonly', (store) => store.get(userId));
    return result ? result.profile : null;
  }

  async saveUserProfile(userId: number, profile: UserProfile): Promise<void> {
    await this.transaction('profiles', 'readwrite', (store) => store.put({ userId, profile }));
  }

  // --- History Operations ---

  async getUserHistory(userId: number): Promise<HistoryItem[]> {
    const db = await this.connect();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('history', 'readonly');
      const store = tx.objectStore('history');
      const index = store.index('userId');
      // GetAll might be slow for massive datasets, but fine for user history here.
      // Cursor would be better for pagination.
      const request = index.getAll(userId);

      request.onsuccess = () => {
        // Map stored items to runtime items (strip internal IDs if needed, but we keep them for deletion)
        const items = request.result.sort((a, b) => b.timestamp - a.timestamp);
        resolve(items);
      };
      request.onerror = () => reject(request.error);
    });
  }

  async addHistoryItem(userId: number, item: Omit<HistoryItem, 'id' | 'timestamp'>): Promise<number> {
    const storedItem: Omit<StoredHistoryItem, 'id'> = {
      userId,
      timestamp: Date.now(),
      ...item
    };
    return this.transaction<number>('history', 'readwrite', (store) => store.add(storedItem));
  }

  async clearUserHistory(userId: number): Promise<void> {
    const db = await this.connect();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('history', 'readwrite');
      const store = tx.objectStore('history');
      const index = store.index('userId');
      const request = index.openCursor(IDBKeyRange.only(userId));

      request.onsuccess = (event) => {
        const cursor = (event.target as IDBRequest).result as IDBCursorWithValue;
        if (cursor) {
          cursor.delete();
          cursor.continue();
        }
      };

      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error);
    });
  }
}

export const db = new Database();

// Secure password handling using Web Crypto API

export async function generateSalt(): Promise<string> {
  const array = new Uint8Array(16);
  window.crypto.getRandomValues(array);
  return Array.from(array)
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

export async function hashPassword(password: string, salt: string): Promise<string> {
  const enc = new TextEncoder();
  const passwordKey = await window.crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits", "deriveKey"]
  );

  const key = await window.crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt: enc.encode(salt),
      iterations: 100000,
      hash: "SHA-256"
    },
    passwordKey,
    { name: "AES-GCM", length: 256 },
    true,
    ["encrypt", "decrypt"]
  );

  const exported = await window.crypto.subtle.exportKey("raw", key);
  return Array.from(new Uint8Array(exported))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

import React, { createContext, useContext, useState, useEffect } from 'react';
import { db, User } from '../lib/db';
import { hashPassword, generateSalt } from '../lib/crypto';

// Minimal user info stored in session
export interface AuthUser {
  id: number;
  email: string;
  name: string;
}

interface AuthContextType {
  user: AuthUser | null;
  isLoading: boolean;
  login: (email: string, pass: string) => Promise<boolean>;
  signup: (data: Record<string, string>) => Promise<{ success: boolean; message: string }>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const SESSION_KEY = 'chicsync_session_uid';

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Restore session on mount
  useEffect(() => {
    const restoreSession = async () => {
      try {
        const storedEmail = sessionStorage.getItem(SESSION_KEY);
        if (storedEmail) {
          const dbUser = await db.getUserByEmail(storedEmail);
          if (dbUser && dbUser.id) {
            setUser({ id: dbUser.id, email: dbUser.email, name: dbUser.name });
          }
        }
      } catch (e) {
        console.error("Session restore failed", e);
      } finally {
        setIsLoading(false);
      }
    };
    restoreSession();
  }, []);

  const login = async (email: string, pass: string): Promise<boolean> => {
    try {
      const dbUser = await db.getUserByEmail(email);
      if (!dbUser) return false;

      const hash = await hashPassword(pass, dbUser.salt);
      if (hash === dbUser.passwordHash && dbUser.id) {
        setUser({ id: dbUser.id, email: dbUser.email, name: dbUser.name });
        sessionStorage.setItem(SESSION_KEY, email);
        return true;
      }
      return false;
    } catch (e) {
      console.error("Login error", e);
      return false;
    }
  };

  const signup = async (data: Record<string, string>): Promise<{ success: boolean; message: string }> => {
    try {
      const existingUser = await db.getUserByEmail(data.email);
      if (existingUser) {
        return { success: false, message: 'An account with this email already exists.' };
      }

      const salt = await generateSalt();
      const passwordHash = await hashPassword(data.password, salt);

      await db.createUser({
        email: data.email,
        name: data.name,
        passwordHash,
        salt,
        createdAt: Date.now()
      });

      return { success: true, message: 'Account created successfully! Please log in.' };
    } catch (e) {
      console.error("Signup error", e);
      return { success: false, message: 'Failed to create account. Please try again.' };
    }
  };

  const logout = () => {
    setUser(null);
    sessionStorage.removeItem(SESSION_KEY);
  };

  return (
    <AuthContext.Provider value={{ user, isLoading, login, signup, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

